y\": 0,\n        \"controlBehavior\": 0\n    },\n     {\n        \"resource\": \"ruoyi-gb28181\",\n        \"count\": 300,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n     {\n        \"resource\": \"ruoyi-jt1078\",\n        \"count\": 300,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    }\n]', 'fb44bf56f06a3b198cee785a33964e58', '2026-03-27 13:35:57', '2026-04-26 20:32:16', 'nacos', '172.18.0.1', '', 'public', '限流策略', NULL, NULL, 'json', NULL, '');
