INSERT INTO `config_info` VALUES (31, 'ruoyi-haikang-isup-dev.yml', 'DEFAULT_GROUP', '# spring配置\nspring:\n  data:\n    redis:\n      host: localhost\n      port: 6379\n      password: 123456\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://localhost:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: haoxin\n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.ruoyi.haikang.isup.**.domain\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\nhaikang-isup:\n  cmsServer:\n    # 注册服务器监听地址(服务器本地地址)\n    ip: 192.168.1.200\n    port: 7660\n\n  dasServer:\n    # DAS地址（此处的IP和端口与设备网页端设置的平台IP地址和端口一致）\n    ip: 192.168.1.200\n    port: 7660\n\n  smsServer:\n    # 取流服务器地址端口（公网对接填入公网地址和端口）\n    ip: 192.168.1.200\n    port: 7665\n    # 取流服务器监听地址端口(服务器本地地址)\n    listenIp: 192.168.1.200\n    listenPort: 7665\n\n  smsBackServer:\n    # 回放流媒体服务器地址端口（公网对接填入公网地址和端口）\n    ip: 192.168.1.200\n    port: 8000\n    # 取流服务器监听地址端口(服务器本地地址)\n    listenIp: 192.168.1.200\n    listenPort: 8000\n\n  voiceSmsServer:\n    # 语音流媒体服务器地址端口（公网对接填入公网地址和端口）\n    ip: 192.168.1.200\n    port: 7500\n    # 语音流媒体服务器监听地址端口(服务器本地地址)\n    listenIp: 192.168.1.200\n    listenPort: 7500\n\n  alarmServer:\n    # 报警服务器地址（公网对接填入公网地址和端口）\n    ip: 192.168.1.200\n    tcpPort: 7663\n    udpPort: 7662\n    #\n    alarmStorage: false\n    # 报警服务器类型：\n    # 0-只支持UDP协议上报\n    # 1-支持UDP、TCP两种协议上报（ISUP4.0）\n    # 2-MQTT(ISUP5.0) (MQTT复用TCP的端口)\n    type: 2\n    # 报警服务器监听地址端口\n    listenIp: 192.168.1.200\n    listenTcpPort: 7663\n    listenUdpPort: 7662\n\n  picServer:\n    # 图片存储服务器地址：IUSP5.0版本接入端口建议固定为6011\n    ip: 192.168.1.200\n    port: 6011\n    # 图片存储服务器类型：\n    # 0-Tomcat\n    # 1-VRB\n    # 2-云存储\n    # 3-KMS\n    # 4-ISUP5.0\n    type: 2\n    # 图片存储服务器监听地址端口\n    listenIp: 192.168.1.200\n    listenPort: 6011\n\n  # ISUP5.0登录秘钥\n  isupKey: 12345678\n\n  # 报警服务器打印事件模式\n  # file=事件保存到文件中\n  # console=事件打印在控制台上\n  eventInfoPrintType: console\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'海康isup生成接口文档\'\n    # 描述\n    description: \'海康isup生成接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip', '95f21b60b198732b6528cadf7b504d0d', '2026-03-28 16:00:45', '2026-04-25 12:58:49', 'nacos_namespace_migrate', '172.18.0.1', '', '', '', NULL, NULL, 'yaml', NULL, '');
