 isupKey: 12345678\n\n  # 报警服务器打印事件模式\n  # file=事件保存到文件中\n  # console=事件打印在控制台上\n  eventInfoPrintType: console\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'海康isup生成接口文档\'\n    # 描述\n    description: \'海康isup生成接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip', '95f21b60b198732b6528cadf7b504d0d', '2026-03-28 16:00:45', '2026-04-25 12:58:49', 'nacos', '172.18.0.1', '', 'public', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` VALUES (33, 'ruoyi-dahua-dev.yml', 'DEFAULT_GROUP', '# spring配置\nspring:\n  data:\n    redis:\n      host: localhost\n      port: 6379\n      password: 123456\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://localhost:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: haoxin\n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.ruoyi.dahua.domain\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\n# dahua配置\ndahua:\n  # [必须修改] dahua服务器的可以是内网IP也可以是公网IP\n  ip: 192.168.1.200\n  # [必须修改] dahua服务器的端口\n  port: 9500\n  # 是否公网\n  isPublicNetwork: false\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'大华sdk生成接口文档\'\n    # 描述\n    description: \'大华sdk生成接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip', 'ab0d966e6c384e20606dab0e5f6a2639', '2026-03-30 15:21:56', '2026-04-25 12:59:05', 'nacos_namespace_migrate', '172.18.0.1', '', '', '', NULL, NULL, 'yaml', NULL, '');
