INSERT INTO `config_info` VALUES (39, 'ruoyi-gb28181-dev.yml', 'DEFAULT_GROUP', '# spring配置\nspring:\n  data:\n    redis:\n      host: localhost\n      port: 6379\n      password: 123456\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://localhost:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: haoxin\n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.ruoyi.gb28181.**.domain\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\n# 作为28181服务器的配置\nsip:\n  ip: 0.0.0.0,192.168.1.200\n  # [可选] 28181服务监听的端口\n  port: 8116\n  # 根据国标6.1.2中规定，domain宜采用ID统一编码的前十位编码。国标附录D中定义前8位为中心编码（由省级、市级、区级、基层编号组成，参照GB/T 2260-2007）\n  # 后两位为行业编码，定义参照附录D.3\n  # 3701020049标识山东济南历下区 信息行业接入\n  # [可选]\n  domain: 4101050000\n  # [可选]\n  id: 41010500002000000001\n  # [可选] 默认设备认证密码，后续扩展使用设备单独密码, 移除密码将不进行校验\n  password: 12345678\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'国标28181生成接口文档\'\n    # 描述\n    description: \'国标28181生成接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip', '7cca6846ff88e0a475953bb63f9b5dfc', '2026-04-23 12:44:01', '2026-04-23 12:45:12', 'nacos_namespace_migrate', '172.18.0.1', '', '', '国标28181配置', NULL, NULL, 'yaml', NULL, '');
