INSERT INTO `his_config_info` VALUES (40, 58, 'ruoyi-gb28181-dev.yml', 'DEFAULT_GROUP', '', '# spring配置\nspring:\n  data:\n    redis:\n      host: localhost\n      port: 6379\n      password: 123456\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://localhost:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: haoxin\n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.ruoyi.gb28181.**.domain\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'国标28181生成接口文档\'\n    # 描述\n    description: \'国标28181生成接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip', '40cb6a914776b056b05f38d5f69a5b91', '2026-04-23 12:45:12', '2026-04-23 04:45:12', 'nacos', '172.18.0.1', 'U', 'public', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"国标28181配置\"}');
INSERT INTO `his_config_info` VALUES (10, 59, 'application-dev.yml', 'DEFAULT_GROUP', '', 'spring:\n  autoconfigure:\n    exclude: com.alibaba.druid.spring.boot3.autoconfigure.DruidDataSourceAutoConfigure\n\n# feign 配置\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n  compression:\n    request:\n      enabled: true\n      min-request-size: 8192\n    response:\n      enabled: true\n\n# 本地文件上传    \nfile:\n    domain: http://127.0.0.1:9300\n    path: D:/ruoyi/uploadPath\n    prefix: /statics\n\n#zlm 默认服务器配置\nmedia:\n  id: hxkj_zlm\n  # [必须修改] zlm服务器的内网IP\n  ip: 192.168.2.200\n  # [必须修改] zlm服务器的http.port\n  http-port: 8092\n  http-ssl-port: 443\n  # [可选] zlm服务器的hook所使用的IP, 默认使用sip.ip\n  hook-ip: 192.168.2.200\n  # [必选选] zlm服务器的hook.admin_params=secret\n  secret: hxkj_zlm\n  #  # [可选] 录像文件存储路径\n  #  record-path: F:/zml/record\n  # [可选] 录像保存时间,单位是天\n  record-day: 3\n  # 启用多端口模式, 多端口模式使用端口区分每路流，兼容性更好。 单端口使用流的ssrc区分， 点播超时建议使用多端口测试\n  rtp:\n    # [可选] 是否启用多端口模式, 开启后会在portRange范围内选择端口用于媒体流传输\n    enable: true\n    # [可选] 在此范围内选择端口用于媒体流传输, 必须提前在zlm上配置该属性，不然自动配置此属性可能不成功\n    port-range: 30500,40500 # 端口范围\n    # [可选] 国标级联在此范围内选择端口发送媒体流,\n    send-port-range: 30000,30500 # 端口范围\n\n# 暴露监控端点\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n', '06b4f4fb8ca89cbcf820903a9fe36c14', '2026-04-23 16:51:50', '2026-04-23 08:51:50', 'nacos', '172.18.0.1', 'U', 'public', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"通用配置\"}');
INSERT INTO `his_config_info` VALUES (10, 60, 'application-dev.yml', 'DEFAULT_GROUP', '', 'spring:\n  autoconfigure:\n    exclude: com.alibaba.druid.spring.boot3.autoconfigure.DruidDataSourceAutoConfigure\n\n# feign 配置\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n  compression:\n    request:\n      enabled: true\n      min-request-size: 8192\n    response:\n      enabled: true\n\n# 本地文件上传    \nfile:\n    domain: http://127.0.0.1:9300\n    path: D:/ruoyi/uploadPath\n    prefix: /statics\n\n#zlm 默认服务器配置\nmedia:\n  id: hxkj_zlm\n  # [必须修改] zlm服务器的内网IP\n  ip: 192.168.1.200\n  # [必须修改] zlm服务器的http.port\n  http-port: 8092\n  http-ssl-port: 443\n  # [可选] zlm服务器的hook所使用的IP, 默认使用sip.ip\n  hook-ip: 192.168.1.200\n  # [必选选] zlm服务器的hook.admin_params=secret\n  secret: hxkj_zlm\n  #  # [可选] 录像文件存储路径\n  #  record-path: F:/zml/record\n  # [可选] 录像保存时间,单位是天\n  record-day: 3\n  # 启用多端口模式, 多端口模式使用端口区分每路流，兼容性更好。 单端口使用流的ssrc区分， 点播超时建议使用多端口测试\n  rtp:\n    # [可选] 是否启用多端口模式, 开启后会在portRange范围内选择端口用于媒体流传输\n    enable: true\n    # [可选] 在此范围内选择端口用于媒体流传输, 必须提前在zlm上配置该属性，不然自动配置此属性可能不成功\n    port-range: 30500,40500 # 端口范围\n    # [可选] 国标级联在此范围内选择端口发送媒体流,\n    send-port-range: 30000,30500 # 端口范围\n\n# 暴露监控端点\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n', '124f4c8838f2e95d150b1903febc0e00', '2026-04-24 12:43:14', '2026-04-24 04:43:14', 'nacos', '172.18.0.1', 'U', 'public', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"通用配置\"}');
INSERT INTO `his_config_info` VALUES (32, 61, 'ruoyi-haikang-isup-dev.yml', 'DEFAULT_GROUP', '', '# spring配置\nspring:\n  data:\n    redis:\n      host: localhost\n      port: 6379\n      password: 123456\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://localhost:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: haoxin\n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.ruoyi.haikang.isup.**.domain\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\nhaikang-isup:\n  cmsServer:\n    # 注册服务器监听地址(服务器本地地址)\n    ip: 192.168.2.200\n    port: 7660\n\n  dasServer:\n    # DAS地址（此处的IP和端口与设备网页端设置的平台IP地址和端口一致）\n    ip: 192.168.2.200\n    port: 7660\n\n  smsServer:\n    # 取流服务器地址端口（公网对接填入公网地址和端口）\n    ip: 192.168.2.200\n    port: 7665\n    # 取流服务器监听地址端口(服务器本地地址)\n    listenIp: 192.168.2.200\n    listenPort: 7665\n\n  smsBackServer:\n    # 回放流媒体服务器地址端口（公网对接填入公网地址和端口）\n    ip: 192.168.2.200\n    port: 8000\n    # 取流服务器监听地址端口(服务器本地地址)\n    listenIp: 192.168.2.200\n    listenPort: 8000\n\n  voiceSmsServer:\n    # 语音流媒体服务器地址端口（公网对接填入公网地址和端口）\n    ip: 192.168.2.200\n    port: 7500\n    # 语音流媒体服务器监听地址端口(服务器本地地址)\n    listenIp: 192.168.2.200\n    listenPort: 7500\n\n  alarmServer:\n    # 报警服务器地址（公网对接填入公网地址和端口）\n    ip: 192.168.2.200\n    tcpPort: 7663\n    udpPort: 7662\n    #\n    alarmStorage: false\n    # 报警服务器类型：\n    # 0-只支持UDP协议上报\n    # 1-支持UDP、TCP两种协议上报（ISUP4.0）\n    # 2-MQTT(ISUP5.0) (MQTT复用TCP的端口)\n    type: 2\n    # 报警服务器监听地址端口\n    listenIp: 192.168.2.200\n    listenTcpPort: 7663\n    listenUdpPort: 7662\n\n  picServer:\n    # 图片存储服务器地址：IUSP5.0版本接入端口建议固定为6011\n    ip: 192.168.2.200\n    port: 6011\n    # 图片存储服务器类型：\n    # 0-Tomcat\n    # 1-VRB\n    # 2-云存储\n    # 3-KMS\n    # 4-ISUP5.0\n    type: 2\n    # 图片存储服务器监听地址端口\n    listenIp: 192.168.2.200\n    listenPort: 6011\n\n  # ISUP5.0登录秘钥\n  isupKey: 12345678\n\n  # 报警服务器打印事件模式\n  # file=事件保存到文件中\n  # console=事件打印在控制台上\n  eventInfoPrintType: console\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'海康isup生成接口文档\'\n    # 描述\n    description: \'海康isup生成接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip', '56446de72512f79abab35a9a2bd40b90', '2026-04-25 12:58:49', '2026-04-25 04:58:49', 'nacos', '172.18.0.1', 'U', 'public', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` VALUES (34, 62, 'ruoyi-dahua-dev.yml', 'DEFAULT_GROUP', '', '# spring配置\nspring:\n  data:\n    redis:\n      host: localhost\n      port: 6379\n      password: 123456\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://localhost:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: haoxin\n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.ruoyi.dahua.domain\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\n# dahua配置\ndahua:\n  # [必须修改] dahua服务器的可以是内网IP也可以是公网IP\n  ip: 192.168.2.200\n  # [必须修改] dahua服务器的端口\n  port: 9500\n  # 是否公网\n  isPublicNetwork: false\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'大华sdk生成接口文档\'\n    # 描述\n    description: \'大华sdk生成接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip', 'da4e5fd394bcf3b61913453af09677d0', '2026-04-25 12:59:05', '2026-04-25 04:59:05', 'nacos', '172.18.0.1', 'U', 'public', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` VALUES (11, 63, 'ruoyi-gateway-dev.yml', 'DEFAULT_GROUP', '', 'spring:\n  data:\n    redis:\n      host: localhost\n      port: 6379\n      password: 123456\n  cloud:\n    gateway:\n      server:\n        webflux:\n          discovery:\n            locator:\n              lowerCaseServiceId: true\n              enabled: true\n          routes:\n            # 认证中心\n            - id: ruoyi-auth\n              uri: lb://ruoyi-auth\n              predicates:\n                - Path=/auth/**\n              filters:\n                # 验证码处理\n                - CacheRequestBody\n                - ValidateCodeFilter\n                - StripPrefix=1\n            # 代码生成\n            - id: ruoyi-gen\n              uri: lb://ruoyi-gen\n              predicates:\n                - Path=/code/**\n              filters:\n                - StripPrefix=1\n            # 定时任务\n            - id: ruoyi-job\n              uri: lb://ruoyi-job\n              predicates:\n                - Path=/schedule/**\n              filters:\n                - StripPrefix=1\n            # 系统模块\n            - id: ruoyi-system\n              uri: lb://ruoyi-system\n              predicates:\n                - Path=/system/**\n              filters:\n                - StripPrefix=1\n            # 文件服务\n            - id: ruoyi-file\n              uri: lb://ruoyi-file\n              predicates:\n                - Path=/file/**\n              filters:\n                - StripPrefix=1\n             # 海康sdk服务\n            - id: ruoyi-haikang\n              uri: lb://ruoyi-haikang\n              predicates:\n                - Path=/haikang/**\n              filters:\n                - StripPrefix=1\n              # 泉视服务\n            - id: ruoyi-qs\n              uri: lb://ruoyi-qs\n              predicates:\n                - Path=/qs/**\n              filters:\n                - StripPrefix=1\n              # 海康isup服务\n            - id: ruoyi-haikang-isup\n              uri: lb://ruoyi-haikang-isup\n              predicates:\n                - Path=/haikangIsup/**\n              filters:\n                - StripPrefix=1\n              # 大华sdk服务\n            - id: ruoyi-dahua\n              uri: lb://ruoyi-dahua\n              predicates:\n                - Path=/dahua/**\n              filters:\n                - StripPrefix=1\n              # zlm服务\n            - id: ruoyi-zlm\n              uri: lb://ruoyi-zlm\n              predicates:\n                - Path=/zlm/**\n              filters:\n                - StripPrefix=1\n              # onvif服务\n            - id: ruoyi-onvif\n              uri: lb://ruoyi-onvif\n              predicates:\n                - Path=/onvif/**\n              filters:\n                - StripPrefix=1\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /*/v2/api-docs\n      - /*/v3/api-docs\n      - /csrf\n      - /zlm/index/hook/**\n      - /zlm/cloudRecord/download/zip\n\n# springdoc配置\nspringdoc:\n  webjars:\n    # 访问前缀\n    prefix:\n', '19f6a037fdacecf35fdd9c6602e223d9', '2026-04-25 14:20:35', '2026-04-25 06:20:36', 'nacos', '172.18.0.1', 'U', 'public', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"网关模块\"}');
INSERT INTO `his_config_info` VALUES (18, 64, 'sentinel-ruoyi-gateway', 'DEFAULT_GROUP', '', '[\n    {\n        \"resource\": \"ruoyi-auth\",\n        \"count\": 500,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n	{\n        \"resource\": \"ruoyi-system\",\n        \"count\": 1000,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n	{\n        \"resource\": \"ruoyi-gen\",\n        \"count\": 200,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n	{\n        \"resource\": \"ruoyi-job\",\n        \"count\": 300,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n    {\n        \"resource\": \"ruoyi-haikang\",\n        \"count\": 300,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n    {\n        \"resource\": \"ruoyi-qs\",\n        \"count\": 300,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n    {\n        \"resource\": \"ruoyi-haikang-isup\",\n        \"count\": 300,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n    {\n        \"resource\": \"ruoyi-dahua\",\n        \"count\": 300,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n     {\n        \"resource\": \"ruoyi-zlm\",\n        \"count\": 300,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    },\n     {\n        \"resource\": \"ruoyi-onvif\",\n        \"count\": 300,\n        \"grade\": 1,\n        \"limitApp\": \"default\",\n        \"strategy\": 0,\n        \"controlBehavior\": 0\n    }\n]', 'f802dbd88c75822553054ea5d305adb3', '2026-04-25 16:53:44', '2026-04-25 08:53:45', 'nacos', '172.18.0.1', 'U', 'public', '', 'formal', '', '{\"type\":\"json\",\"src_user\":\"nacos\",\"c_desc\":\"限流策略\"}');
